mapper.select:
select
f.FileTitle as fileTitle,
mn.*
from Web_Audit_Log mn
left join Sys_File f on f.fileid=mn.Sal_Form_Id

    
        and mn.Sal_Form_Id=#{params.salFormId}
    
    
        and mn.Sal_Type=#{params.salType}
    
    
        and INSTR(mn.Create_Uname,#{params.createUname})
    
    
        and INSTR(f.FileTitle,#{params.fileTitle})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc
